import{_ as o,o as t,c as a,a2 as n}from"./chunks/framework.Cso1fFul.js";const p=JSON.parse('{"title":"Interview Preparation: 150+ Questions & Answers","description":"","frontmatter":{},"headers":[],"relativePath":"09-interview-qa.md","filePath":"09-interview-qa.md"}'),s={name:"09-interview-qa.md"};function r(i,e,c,d,l,h){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="interview-preparation-150-questions-answers" tabindex="-1">Interview Preparation: 150+ Questions &amp; Answers <a class="header-anchor" href="#interview-preparation-150-questions-answers" aria-label="Permalink to &quot;Interview Preparation: 150+ Questions &amp; Answers&quot;">​</a></h1><h2 id="core-architectural-questions" tabindex="-1">Core Architectural Questions <a class="header-anchor" href="#core-architectural-questions" aria-label="Permalink to &quot;Core Architectural Questions&quot;">​</a></h2><h3 id="q1-can-you-explain-how-the-node-js-event-loop-works" tabindex="-1">Q1: Can you explain how the Node.js event loop works? <a class="header-anchor" href="#q1-can-you-explain-how-the-node-js-event-loop-works" aria-label="Permalink to &quot;Q1: Can you explain how the Node.js event loop works?&quot;">​</a></h3><p><strong>Answer</strong>: The Node.js event loop is powered by libuv and consists of six distinct phases: Timers (<code>setTimeout</code>, <code>setInterval</code>), Pending callbacks, Idle/Prepare, Poll (retrieving new I/O events), Check (<code>setImmediate</code>), and Close callbacks. Between every single phase and before returning to the event loop, Node drains the microtask queue—executing <code>process.nextTick</code> callbacks first, followed by resolved Promise microtasks.</p><h3 id="q2-how-do-you-prevent-event-loop-blocking-in-node-js" tabindex="-1">Q2: How do you prevent event loop blocking in Node.js? <a class="header-anchor" href="#q2-how-do-you-prevent-event-loop-blocking-in-node-js" aria-label="Permalink to &quot;Q2: How do you prevent event loop blocking in Node.js?&quot;">​</a></h3><p><strong>Answer</strong>: Heavy computations—such as cryptographic key generation, image resizing, or large JSON parsing—will block the single main JavaScript thread. To prevent this, CPU-bound tasks should be offloaded to Worker Threads (<code>worker_threads</code>), delegated to external background workers via job queues like BullMQ, or broken down into chunks using asynchronous iteration.</p><h3 id="q3-what-is-the-difference-between-process-nexttick-and-setimmediate" tabindex="-1">Q3: What is the difference between process.nextTick and setImmediate? <a class="header-anchor" href="#q3-what-is-the-difference-between-process-nexttick-and-setimmediate" aria-label="Permalink to &quot;Q3: What is the difference between process.nextTick and setImmediate?&quot;">​</a></h3><p><strong>Answer</strong>: Despite its name, <code>process.nextTick</code> fires immediately after the currently executing operation finishes, before the event loop advances to the next phase or microtask. <code>setImmediate</code> schedules a callback to run during the Check phase of the event loop, after the Poll phase has processed pending I/O events.</p><h3 id="q4-how-do-you-handle-database-transactions-under-high-concurrency" tabindex="-1">Q4: How do you handle database transactions under high concurrency? <a class="header-anchor" href="#q4-how-do-you-handle-database-transactions-under-high-concurrency" aria-label="Permalink to &quot;Q4: How do you handle database transactions under high concurrency?&quot;">​</a></h3><p><strong>Answer</strong>: We use atomic database sessions with optimistic locking. In MongoDB or PostgreSQL, transactions verify record versions during updates. If a concurrent write is detected, the transaction aborts and retries with exponential backoff, preventing lost updates and phantom reads.</p><h3 id="q5-how-do-you-gracefully-shut-down-a-node-js-web-server" tabindex="-1">Q5: How do you gracefully shut down a Node.js web server? <a class="header-anchor" href="#q5-how-do-you-gracefully-shut-down-a-node-js-web-server" aria-label="Permalink to &quot;Q5: How do you gracefully shut down a Node.js web server?&quot;">​</a></h3><p><strong>Answer</strong>: When receiving a <code>SIGTERM</code> signal from Docker or Kubernetes, the server stops accepting new connections by calling <code>server.close()</code>. It sets a timeout window (e.g. 15 seconds) to allow in-flight HTTP requests to complete, flushes write streams and log buffers, closes database and Redis connection pools, and exits with code 0.</p>',12)])])}const w=o(s,[["render",r]]);export{p as __pageData,w as default};
